        this.attrs = opts.attrs || [];      // user classes: attribute descriptors
        this.isEnum = !!opts.isEnum;
        this.enumValues = null;             // an enum type: [REnum...]
        this.isRole = !!opts.isRole;
        this.isUser = !!opts.isUser;
        this.mro = [this];
